static const TText *const *const KAllTables[ELangIdCount] =
	{
	KTable_en,
	KTable_uk,
	KTable_zh,
	KTable_de,
	KTable_fr,
	KTable_es,
	KTable_ru,
	KTable_pt,
	KTable_it,
	KTable_pl,
	KTable_tr,
	KTable_ja,
	KTable_hi,
	KTable_ar,
	KTable_ko,
	};

static const TText *const KAllLangNames[ELangIdCount] =
	{
	KLangName_en,
	KLangName_uk,
	KLangName_zh,
	KLangName_de,
	KLangName_fr,
	KLangName_es,
	KLangName_ru,
	KLangName_pt,
	KLangName_it,
	KLangName_pl,
	KLangName_tr,
	KLangName_ja,
	KLangName_hi,
	KLangName_ar,
	KLangName_ko,
	};

static TInt gActiveLang = 0;
static TPtrC gActiveStrings[EStrCount];
static TPtrC gLangNamePtrs[ELangIdCount];
static TBool gInitialized = EFalse;

static void I18nEnsureInit()
	{
	if (!gInitialized)
		{
		for (TInt i = 0; i < ELangIdCount; i++)
			gLangNamePtrs[i].Set(KAllLangNames[i]);
		I18nSetLanguage(gActiveLang);
		gInitialized = ETrue;
		}
	}

void I18nSetLanguage(TInt aLang)
	{
	if (aLang < 0 || aLang >= ELangIdCount)
		aLang = 0;
	gActiveLang = aLang;
	const TText *const *table = KAllTables[gActiveLang];
	for (TInt i = 0; i < EStrCount; i++)
		gActiveStrings[i].Set(table[i]);
	}

TInt I18nLanguageCount()
	{
	return ELangIdCount;
	}

const TDesC &I18nLanguageName(TInt aLang)
	{
	I18nEnsureInit();
	if (aLang < 0 || aLang >= ELangIdCount)
		return gLangNamePtrs[0];
	return gLangNamePtrs[aLang];
	}

const TDesC &Tr(TInt aId)
	{
	I18nEnsureInit();
	if (aId < 0 || aId >= EStrCount)
		return KNullDesC;
	return gActiveStrings[aId];
	}

TInt I18nDetectLanguage()
	{
	const TLanguage l = User::Language();
	switch (l)
		{
		case ELangUkrainian:             return ELangIdUkrainian;
		case ELangTaiwanChinese:
		case ELangHongKongChinese:
		case ELangPrcChinese:             return ELangIdChinese;
		case ELangGerman:
		case ELangSwissGerman:
		case ELangAustrian:               return ELangIdGerman;
		case ELangFrench:
		case ELangSwissFrench:
		case ELangBelgianFrench:
		case ELangInternationalFrench:
		case ELangCanadianFrench:         return ELangIdFrench;
		case ELangSpanish:
		case ELangInternationalSpanish:
		case ELangLatinAmericanSpanish:   return ELangIdSpanish;
		case ELangRussian:               return ELangIdRussian;
		case ELangPortuguese:
		case ELangBrazilianPortuguese:   return ELangIdPortuguese;
		case ELangItalian:
		case ELangSwissItalian:          return ELangIdItalian;
		case ELangPolish:                return ELangIdPolish;
		case ELangTurkish:
		case ELangCyprusTurkish:         return ELangIdTurkish;
		case ELangJapanese:              return ELangIdJapanese;
		case ELangHindi:                 return ELangIdHindi;
		case ELangArabic:                return ELangIdArabic;
		case ELangKorean:                return ELangIdKorean;
		default:                         return ELangIdEnglish;
		}
	}
